Out_Fifo out_fifo_create( UInt8 size ) 
{
    UInt8 i ;

    Out_Fifo out_fifo = (Out_Fifo)os_mem_request( sizeof( struct s_Out_Fifo) ) ;
    
    out_fifo->q_p = fifo_create(); 
	out_fifo->q_f = fifo_create();
		
    out_fifo->out = out_create( NULL ) ; 

    for( i = 0 ; i < size ; i ++ )
    {
        Out_Fifo_Node *node = (Out_Fifo_Node*)os_mem_request( sizeof ( struct s_Out_Fifo_Node) ); 
        
        fifo_insert( out_fifo->q_f  , (Fifo_Node*) node );
    }
    
    return out_fifo ; 
}

